package com.nm.fragmentsclean.userApplicationContext.write.businesslogic.usecases;
import com.nm.fragmentsclean.userApplicationContext.write.businesslogic.models.AvatarMediaChangedEvent;
import com.nm.fragmentsclean.sharedKernel.businesslogic.commandStatus.BusinessCommandRejectedException;import com.nm.fragmentsclean.sharedKernel.businesslogic.models.*;import com.nm.fragmentsclean.sharedKernel.businesslogic.models.command.CommandHandler;import com.nm.fragmentsclean.userApplicationContext.write.businesslogic.gateways.*;import jakarta.transaction.Transactional;
public class RemoveAvatarCommandHandler implements CommandHandler<RemoveAvatarCommand>{private final AppUserRepository users;private final AvatarMediaRepository media;private final DomainEventPublisher events;private final DateTimeProvider clock;public RemoveAvatarCommandHandler(AppUserRepository users,AvatarMediaRepository media,DomainEventPublisher events,DateTimeProvider clock){this.users=users;this.media=media;this.events=events;this.clock=clock;}@Override@Transactional public void execute(RemoveAvatarCommand command){var user=users.findById(command.userId()).orElseThrow(()->new BusinessCommandRejectedException("APP_USER_NOT_FOUND","User not found"));var now=clock.now();boolean changed=user.removeAvatar(now);media.byUser(command.userId()).forEach(item->{if(item.snapshot().status()!=com.nm.fragmentsclean.userApplicationContext.write.businesslogic.models.AvatarMediaStatus.RETIRED&&item.requestDeletion(now)){media.save(item);events.publish(AvatarMediaChangedEvent.from(item.snapshot(),command.commandId(),null));}});if(changed)users.save(user);user.domainEvents().forEach(events::publish);user.clearDomainEvents();}}
